const items=[["dashboard","⌂","Dashboard"],["pos","▣","Point of sale"],["saleslog","₹","Sales log"],["inventory","▦","Products & inventory"],["purchases","▤","Purchasing"],["suppliers","♧","Suppliers"],["customers","♙","Customers & loyalty"],["expenses","$","Expenses"],["reports","▥","Reports"],["audit","◎","Audit log"]];
const money=n=>new Intl.NumberFormat("en-US",{style:"currency",currency:gb?.settings.currency||"USD"}).format(n||0),date=x=>new Date(x).toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"});
async function api(u,o={}){o.headers={...(o.headers||{}),"content-type":"application/json",authorization:`Bearer ${token}`};const r=await fetch(u,o),d=await r.json().catch(()=>({}));if(r.status===401){location.href="/";throw Error("Sign in required")}if(!r.ok)throw Error(d.error||"Request failed");return d}
function toast(t,b=false){const e=$("#gtoast");e.textContent=t;e.style.cssText=`position:fixed;right:22px;top:20px;z-index:50;background:${b?"#b5473d":"#173b2b"};color:#fff;padding:12px 18px;border-radius:8px`;setTimeout(()=>e.textContent="",2500)}
function modal(t,b){document.body.insertAdjacentHTML("beforeend",`<div class="modal"><div class="modalbox"><div class="modalhead"><h2>${t}</h2><button onclick="closeM()">×</button></div>${b}</div></div>`)}window.closeM=()=>$(".modal")?.remove();
const head=(t,s,a="")=>`<div class="pagehead"><div><h1>${t}</h1><p>${s}</p></div>${a}</div>`,table=(h,r)=>`<div class="table"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${r||`<tr><td colspan="${h.length}" class="empty">No records yet</td></tr>`}</tbody></table></div>`;
function toggleNav(open){$("aside").classList.toggle("open",open);$("#navBackdrop").classList.toggle("open",open);document.body.style.overflow=open?"hidden":""}
async function init(){if(!token)return location.href="/";gb=await api("/api/grocery/bootstrap");$("#gnav").innerHTML=items.map(x=>`<button data-p="${x[0]}">${x[1]} &nbsp;${x[2]}</button>`).join("");$$("nav button").forEach(b=>b.onclick=()=>route(b.dataset.p));route("dashboard")}$("#productSwitch").onclick=()=>location.href="/";$(".menu").onclick=()=>toggleNav(true);$("#closeNav").onclick=()=>toggleNav(false);$("#navBackdrop").onclick=()=>toggleNav(false);document.addEventListener("keydown",e=>{if(e.key==="Escape")toggleNav(false)});
async function route(p){toggleNav(false);$$("nav button").forEach(b=>b.classList.toggle("active",b.dataset.p===p));$("#gtitle").textContent=items.find(x=>x[0]===p)[2];$("#gcontent").innerHTML='<div class="empty">Loading…</div>';try{await pages[p]()}catch(e){toast(e.message,true)}}
const pages={};
pages.dashboard=async()=>{gb=await api("/api/grocery/bootstrap");const [sales,products]=await Promise.all([api("/api/grocery/sales"),api("/api/grocery/products")]);$("#gcontent").innerHTML=`<div class="welcome"><div><small>STORE COMMAND CENTER</small><h1>Good day, Nischal.</h1><p>Your store is ready for customers and operating locally.</p></div><div><b>${new Date().toLocaleDateString("en-US",{weekday:"long",day:"numeric",month:"long"})}</b></div></div><div class="stats">${[["Today's sales",money(gb.stats.sales),"Live revenue"],["Transactions",gb.stats.transactions,"Completed bills"],["Gross profit",money(gb.stats.profit),"Before expenses"],["Inventory value",money(gb.stats.inventoryValue),"At cost"],["Low stock",gb.stats.lowStock,"Needs attention"]].map(x=>`<div class="stat"><small>${x[0]}</small><b>${x[1]}</b><em>${x[2]}</em></div>`).join("")}</div><div class="grid2"><div class="card"><div class="cardhead"><h3>Recent sales</h3><button class="secondary" onclick="route('pos')">Open POS</button></div>${saleTable(sales.slice(0,6))}</div><div class="card"><h3>Inventory alerts</h3>${products.filter(p=>p.stock<=p.reorder).map(p=>`<div class="alert"><b>${p.name}</b><br>${p.stock} ${p.unit} remaining • reorder at ${p.reorder}</div>`).join("")||"<p>Stock levels are healthy.</p>"}</div></div>`};
pages.pos=async()=>{gb=await api("/api/grocery/bootstrap");$("#gcontent").innerHTML=head("Point of sale","Fast checkout with Cash, eSewa, Khalti, Bank or split payment")+`<div class="pos"><div><div class="search"><input id="psearch" placeholder="Scan barcode or search product…"><button class="secondary" onclick="clearCart()">Clear</button></div><div class="products" id="productGrid"></div></div><div class="card cart"><h3>Current sale</h3><div id="cartRows"></div><div class="totals" id="totals"></div><div class="alert">Payment can be divided between Cash, eSewa, Khalti and Bank.</div><button class="primary checkout" onclick="checkout()">Choose payment & complete</button></div></div>`;renderProducts(gb.products);renderCart();$("#psearch").oninput=e=>renderProducts(gb.products.filter(p=>(p.name+p.barcode).toLowerCase().includes(e.target.value.toLowerCase())))};
function renderProducts(ps){$("#productGrid").innerHTML=ps.map(p=>`<button class="product" onclick="addCart('${p.id}')"><span>${({Dairy:"🥛",Bakery:"🍞",Fruits:"🍎",Beverages:"💧"})[p.category]||"🛒"}</span><b>${p.name}</b><small>${p.stock} ${p.unit} in stock</small><strong>${money(p.price)}</strong></button>`).join("")}
window.addCart=id=>{const p=gb.products.find(x=>x.id===id),x=cart.find(x=>x.id===id);if(x)x.qty++;else cart.push({...p,qty:1});renderCart()};window.clearCart=()=>{cart=[];renderCart()};
function renderCart(){if(!$("#cartRows"))return;$("#cartRows").innerHTML=cart.map(x=>`<div class="cartrow"><span><b>${x.name}</b><small>${money(x.price)} each</small></span><input type="number" min="1" max="${x.stock}" value="${x.qty}" onchange="setQty('${x.id}',this.value)"><button onclick="removeCart('${x.id}')">×</button></div>`).join("")||'<div class="empty">Scan or select products</div>';const sub=cart.reduce((a,x)=>a+x.price*x.qty,0),tax=sub*(gb.settings.taxRate/100);$("#totals").innerHTML=`<div><span>Subtotal</span><b>${money(sub)}</b></div><div><span>Tax (${gb.settings.taxRate}%)</span><b>${money(tax)}</b></div><div class="grand"><span>Total</span><b>${money(sub+tax)}</b></div>`}
window.setQty=(id,q)=>{const x=cart.find(x=>x.id===id);x.qty=Math.max(1,Math.min(x.stock,Number(q)));renderCart()};window.removeCart=id=>{cart=cart.filter(x=>x.id!==id);renderCart()};
window.checkout=()=>{if(!cart.length)return toast("Cart is empty.",true);const subtotal=cart.reduce((sum,x)=>sum+x.price*x.qty,0),total=subtotal+subtotal*(gb.settings.taxRate/100);modal("Complete sale",`<form id="checkoutForm" class="form"><div class="full alert"><b>Bill total: ${money(total)}</b><br>Example: Cash 25 + eSewa 75 = 100.</div><label>Cash<input name="cash" type="number" min="0" step=".01" value="0"></label><label>eSewa<input name="esewa" type="number" min="0" step=".01" value="0"></label><label>Khalti<input name="khalti" type="number" min="0" step=".01" value="0"></label><label>Bank<input name="bank" type="number" min="0" step=".01" value="0"></label><div id="bankFields" class="full form hidden"><label>Bank name<input name="bankName" placeholder="Example: Nabil Bank"></label><label>Bank / transaction details<input name="bankDetails" placeholder="Voucher, account or transaction ID"></label></div><div id="splitCheck" class="full alert"></div><button id="finishSale" class="primary full" disabled>Complete paid sale</button></form>`);const form=$("#checkoutForm"),fields=[form.elements.cash,form.elements.esewa,form.elements.khalti,form.elements.bank],sync=()=>{const paid=fields.reduce((sum,input)=>sum+Number(input.value||0),0),remaining=total-paid,balanced=Math.abs(remaining)<.009;$("#splitCheck").innerHTML=`Paid: <b>${money(paid)}</b> • ${balanced?"Fully paid":remaining>0?`Remaining: <b>${money(remaining)}</b>`:`Overpaid: <b>${money(Math.abs(remaining))}</b>`}`;$("#finishSale").disabled=!balanced;$("#bankFields").classList.toggle("hidden",Number(form.elements.bank.value||0)<=0);form.elements.bankName.required=Number(form.elements.bank.value||0)>0};fields.forEach(input=>input.oninput=sync);sync();form.onsubmit=async event=>{event.preventDefault();try{const values=Object.fromEntries(new FormData(form)),payments=[{method:"Cash",amount:Number(values.cash||0)},{method:"eSewa",amount:Number(values.esewa||0)},{method:"Khalti",amount:Number(values.khalti||0)},{method:"Bank",amount:Number(values.bank||0),bankName:values.bankName,bankDetails:values.bankDetails}].filter(x=>x.amount>0),sale=await api("/api/grocery/sales",{method:"POST",body:JSON.stringify({items:cart.map(x=>({id:x.id,name:x.name,qty:x.qty,price:x.price})),payments})});cart=[];closeM();modal("Sale completed",`<div style="text-align:center"><div style="font-size:45px;color:#26734d">✓</div><h2>${sale.receipt}</h2><p>Total received</p><h1>${money(sale.total)}</h1><p>${sale.payments.map(x=>`${x.method}: ${money(x.amount)}${x.bankName?` (${x.bankName})`:""}`).join("<br>")}</p><p>${new Date(sale.createdAt).toLocaleString()}</p><button class="primary" onclick="closeM();route('pos')">New sale</button></div>`)}catch(error){toast(error.message,true)}}};
pages.inventory=async()=>{inventoryProducts=await api("/api/grocery/products");const p=inventoryProducts;$("#gcontent").innerHTML=head("Products & inventory","Complete product, pricing, batch, expiry and stock records",`<button class="primary" onclick="newProduct()">+ Add product</button>`)+`<div class="card"><div class="search"><input id="inventorySearch" placeholder="Search product, SKU, barcode, brand, supplier, batch or location…"><small id="inventoryCount">${p.length} products</small></div><div id="inventoryRows">${inventoryTable(p)}</div></div>`;$("#inventorySearch").oninput=event=>{const term=event.target.value.trim().toLowerCase(),rows=term?p.filter(x=>[x.id,x.name,x.sku,x.barcode,x.brand,x.supplier,x.category,x.batchNumber,x.location,x.status].some(value=>String(value||"").toLowerCase().includes(term))):p;$("#inventoryRows").innerHTML=inventoryTable(rows);$("#inventoryCount").textContent=`${rows.length} of ${p.length} products`}};
function inventoryTable(p){return table(["Product","SKU / barcode","Brand / supplier","Category / location","Pricing / margin","Stock limits","Batch / expiry","Status",""],p.map(x=>{const margin=Number(x.price)>0?(Number(x.price)-Number(x.cost))/Number(x.price)*100:0;return`<tr><td>${x.imageData?`<img src="${x.imageData}" alt="" style="width:38px;height:38px;object-fit:cover;border-radius:6px;float:left;margin-right:8px">`:""}<b>${x.name}</b><br><small>${x.description||x.id}</small></td><td>${x.sku||"—"}<br><small>${x.barcode}</small></td><td>${x.brand||"—"}<br><small>${x.supplier||"—"}</small></td><td>${x.category}<br><small>${x.location||"No shelf set"}</small></td><td>Cost ${money(x.cost)}<br><b>${money(x.price)}</b><br><small>${margin.toFixed(1)}% margin${x.discountPrice?` • Promo ${money(x.discountPrice)}`:""}</small></td><td class="${x.stock<=x.reorder?"low":""}">${x.stock} ${x.sellingUnit||x.unit}<br><small>Min ${x.minStock||0} • Reorder ${x.reorder} • Max ${x.maxStock||"—"}</small></td><td>${x.batchNumber||"—"}<br><small>${x.trackExpiry===false?"No expiry tracking":x.expiry?`Expires ${date(x.expiry)}`:"Expiry not set"}</small></td><td><span class="badge ${x.status==="Active"?"green":"orange"}">${x.status||"Active"}</span><br><small>${x.variants?.length||0} variants</small></td><td><button class="secondary" onclick="editProduct('${x.id}')">Edit</button></td></tr>`}).join(""))}
const productForm=x=>`<form id="productForm" class="form"><label>Product name<input name="name" value="${x?.name||""}" required></label><label>SKU / internal code<input name="sku" value="${x?.sku||""}" placeholder="Example: RICE-5KG"></label><label>Barcode<input name="barcode" value="${x?.barcode||""}" required></label><label>Category<input name="category" value="${x?.category||""}" required></label><label>Brand / manufacturer<input name="brand" value="${x?.brand||""}"></label><label>Supplier<input name="supplier" value="${x?.supplier||""}"></label><label class="full">Description<textarea name="description">${x?.description||""}</textarea></label><label>Cost price<input name="cost" type="number" min="0" step=".01" value="${x?.cost||0}" required></label><label>Selling price<input name="price" type="number" min="0" step=".01" value="${x?.price||0}" required></label><label>Promotional price<input name="discountPrice" type="number" min="0" step=".01" value="${x?.discountPrice||0}"></label><label>Tax / VAT %<input name="taxRate" type="number" min="0" step=".01" value="${x?.taxRate??gb.settings.taxRate}"></label><div id="marginPreview" class="alert full"></div><label>Base unit<input name="unit" value="${x?.unit||"piece"}"></label><label>Pack size<input name="packSize" value="${x?.packSize||""}" placeholder="Example: 12 pieces or 500 g"></label><label>Purchase unit<input name="purchaseUnit" value="${x?.purchaseUnit||x?.unit||"case"}"></label><label>Selling unit<input name="sellingUnit" value="${x?.sellingUnit||x?.unit||"piece"}"></label><label>Current / opening stock<input name="stock" type="number" min="0" step=".01" value="${x?.stock||0}"></label><label>Opening-stock date<input name="openingStockDate" type="date" value="${x?.openingStockDate||new Date().toISOString().slice(0,10)}"></label><label>Minimum stock<input name="minStock" type="number" min="0" step=".01" value="${x?.minStock||0}"></label><label>Reorder level<input name="reorder" type="number" min="0" step=".01" value="${x?.reorder||5}"></label><label>Maximum stock<input name="maxStock" type="number" min="0" step=".01" value="${x?.maxStock||0}"></label><label>Storage / shelf location<input name="location" value="${x?.location||""}" placeholder="Example: Aisle 2, Rack B"></label><label>Batch / lot number<input name="batchNumber" value="${x?.batchNumber||""}"></label><label>Manufacturing date<input name="manufacturingDate" type="date" value="${x?.manufacturingDate||""}"></label><label><input name="trackExpiry" type="checkbox" ${x?.trackExpiry===false?"":"checked"}> Track product expiry</label><label>Expiry date<input name="expiry" type="date" value="${x?.expiry||""}"></label><label>Expiry warning days<input name="expiryWarningDays" type="number" min="0" value="${x?.expiryWarningDays??30}"></label><label>Status<select name="status">${["Active","Inactive","Discontinued"].map(status=>`<option ${status===(x?.status||"Active")?"selected":""}>${status}</option>`).join("")}</select></label><label class="full">Variants (one per line)<textarea name="variantsText" placeholder="500 g | 120 | 8900001&#10;1 kg | 220 | 8900002">${(x?.variants||[]).map(v=>`${v.name} | ${v.price||0} | ${v.barcode||""}`).join("\n")}</textarea></label><label class="full">Product image (maximum 500 KB)<input name="image" type="file" accept="image/*"></label><button class="primary full">Save product</button></form>`;
window.newProduct=()=>{modal("Add product",productForm());bindProduct()};window.editProduct=id=>{const x=inventoryProducts.find(product=>product.id===id);if(!x)return;modal(`Edit ${x.name}`,productForm(x));bindProduct(x.id)};function bindProduct(id){const form=$("#productForm"),syncMargin=()=>{const cost=Number(form.elements.cost.value||0),price=Number(form.elements.price.value||0),profit=price-cost,margin=price>0?profit/price*100:0;$("#marginPreview").innerHTML=`Profit per selling unit: <b>${money(profit)}</b> • Gross margin: <b>${margin.toFixed(2)}%</b>`},syncExpiry=()=>{const tracked=form.elements.trackExpiry.checked;form.elements.expiry.disabled=!tracked;form.elements.expiryWarningDays.disabled=!tracked};form.elements.cost.oninput=syncMargin;form.elements.price.oninput=syncMargin;form.elements.trackExpiry.onchange=syncExpiry;syncMargin();syncExpiry();form.onsubmit=async e=>{e.preventDefault();try{const raw=Object.fromEntries(new FormData(form)),image=form.elements.image.files[0],variants=String(raw.variantsText||"").split("\n").map(line=>line.trim()).filter(Boolean).map(line=>{const [name,price,barcode]=line.split("|").map(v=>v.trim());return{name,price:Number(price||0),barcode:barcode||""}}),payload={...raw,trackExpiry:form.elements.trackExpiry.checked,variants};delete payload.image;delete payload.variantsText;if(image){if(image.size>500000)throw Error("Product image must be smaller than 500 KB.");payload.imageName=image.name;payload.imageData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error("Could not read image."));reader.readAsDataURL(image)})}await api(id?`/api/grocery/products/${id}`:"/api/grocery/products",{method:id?"PATCH":"POST",body:JSON.stringify(payload)});closeM();toast("Product saved");route("inventory")}catch(x){toast(x.message,true)}}}
pages.purchases=async()=>{const [p,s,products]=await Promise.all([api("/api/grocery/purchases"),api("/api/grocery/suppliers"),api("/api/grocery/products")]);window.purchaseRows=p;window.purchaseSuppliers=s;window.purchaseProducts=products;const outstanding=p.reduce((sum,x)=>sum+Number(x.outstanding??x.total),0),received=p.filter(x=>x.receivingStatus==="Received"||x.status==="Received").length;$("#gcontent").innerHTML=head("Purchasing","Purchase orders, receiving, supplier payments and returns",`<div><button class="secondary" onclick="exportPurchases()">Export CSV</button> <button class="primary" onclick="newPurchase()">+ Purchase order</button></div>`)+`<div class="grid3"><div class="stat"><small>Purchase value</small><b>${money(p.reduce((sum,x)=>sum+Number(x.total||0),0))}</b><em>${p.length} orders</em></div><div class="stat"><small>Supplier outstanding</small><b>${money(outstanding)}</b><em>Unpaid and partially paid</em></div><div class="stat"><small>Fully received</small><b>${received}</b><em>${p.length-received} still open</em></div></div><div class="card"><div class="search"><input id="purchaseSearch" placeholder="Search PO, invoice, supplier, product, status or payment…"><select id="purchaseStatus"><option value="">All statuses</option>${["Draft","Pending approval","Ordered","Partially received","Received","Rejected","Cancelled"].map(x=>`<option>${x}</option>`).join("")}</select><small id="purchaseCount">${p.length} orders</small></div><div id="purchaseRows">${purchaseTable(p)}</div></div>`;const filter=()=>{const term=$("#purchaseSearch").value.toLowerCase(),status=$("#purchaseStatus").value,rows=p.filter(x=>(!status||x.status===status||x.receivingStatus===status)&&[x.id,x.poNumber,x.supplierInvoice,x.supplier,x.status,x.receivingStatus,x.paymentStatus,...(x.items||[]).flatMap(i=>[i.productName,i.sku,i.batchNumber])].some(v=>String(v||"").toLowerCase().includes(term)));$("#purchaseRows").innerHTML=purchaseTable(rows);$("#purchaseCount").textContent=`${rows.length} of ${p.length} orders`};$("#purchaseSearch").oninput=filter;$("#purchaseStatus").onchange=filter};
function purchaseTable(rows){return table(["PO / invoice","Supplier","Dates","Products","Amounts","Receiving","Payment","Status","Documents / audit","Actions"],rows.map(p=>`<tr><td><b>${p.poNumber||p.id}</b><br><small>${p.supplierInvoice||"No invoice"}</small></td><td>${p.supplier}</td><td>${date(p.date)}<br><small>Expected: ${p.expectedDate?date(p.expectedDate):"—"}<br>Due: ${p.dueDate?date(p.dueDate):"—"}</small></td><td>${(p.items||[]).map(i=>`${i.productName}: ${i.orderedQty||i.quantity} ${i.unit}`).join("<br>")||"Legacy purchase"}</td><td><b>${money(p.total)}</b><br><small>Tax ${money(p.tax)} • Freight ${money(p.shipping)}</small></td><td><span class="badge ${p.receivingStatus==="Received"?"green":"orange"}">${p.receivingStatus||p.status}</span><br><small>${(p.items||[]).reduce((s,i)=>s+Number(i.receivedQty||0),0)} received</small></td><td><b>${p.paymentStatus||"Unpaid"}</b><br><small>Paid ${money(p.paidAmount)}<br>Due ${money(p.outstanding??p.total)}</small></td><td><span class="badge ${["Received","Ordered"].includes(p.status)?"green":"orange"}">${p.status}</span><br><small>${p.approvedBy?`By ${p.approvedBy}`:""}</small></td><td>${p.documentData?`<button class="secondary" onclick="openPurchaseDocument('${p.id}')">Invoice</button>`:"No file"}<br><button class="secondary" onclick="purchaseHistory('${p.id}')">History</button></td><td><div style="display:grid;gap:5px">${p.status==="Pending approval"?`<button class="primary" onclick="approvePurchase('${p.id}',true)">Approve</button>`:""}${!["Draft","Pending approval","Rejected","Cancelled"].includes(p.status)&&p.receivingStatus!=="Received"?`<button class="secondary" onclick="receivePurchase('${p.id}')">Receive</button>`:""}${Number(p.outstanding??p.total)>0?`<button class="secondary" onclick="payPurchase('${p.id}')">Pay</button>`:""}${(p.items||[]).some(i=>Number(i.receivedQty)>Number(i.returnedQty||0))?`<button class="secondary" onclick="returnPurchase('${p.id}')">Return</button>`:""}<button class="secondary" onclick="printPurchase('${p.id}')">Print</button></div></td></tr>`).join(""))}
window.newPurchase=()=>{modal("New purchase order",`<form id="purchaseForm" class="form"><label>PO number<input name="poNumber" placeholder="Auto-generated if blank"></label><label>Supplier invoice<input name="supplierInvoice"></label><label>Supplier<select name="supplierId" required><option value="">Select supplier</option>${purchaseSuppliers.map(x=>`<option value="${x.id}">${x.name}</option>`).join("")}</select></label><label>Order date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Expected delivery<input name="expectedDate" type="date"></label><label>Payment due date<input name="dueDate" type="date"></label><label>Status<select name="status"><option>Draft</option><option>Ordered</option></select></label><label>Shipping / handling<input name="shipping" type="number" min="0" step=".01" value="0"></label><label>Other costs<input name="otherCosts" type="number" min="0" step=".01" value="0"></label><h3 class="full">Products</h3><div id="purchaseItems" class="full"></div><button class="secondary full" type="button" onclick="addPurchaseLine()">+ Add product line</button><div id="purchaseTotal" class="alert full"></div><label class="full">Supplier invoice / delivery note<input name="document" type="file" accept="image/*,.pdf"></label><label class="full">Purchase notes<textarea name="notes"></textarea></label><label class="full">Internal remarks<textarea name="internalNotes"></textarea></label><button class="primary full">Create purchase order</button></form>`);addPurchaseLine();const form=$("#purchaseForm");[form.elements.shipping,form.elements.otherCosts].forEach(x=>x.oninput=calculatePurchase);form.onsubmit=submitPurchase};
window.addPurchaseLine=()=>{const key=Date.now()+Math.random(),row=document.createElement("div");row.className="form purchase-line";row.dataset.key=key;row.style.cssText="border:1px solid var(--line);padding:12px;border-radius:8px;margin-bottom:10px";row.innerHTML=`<label>Product<select name="productId" required><option value="">Select</option>${purchaseProducts.map(x=>`<option value="${x.id}" data-cost="${x.cost}" data-tax="${x.taxRate??gb.settings.taxRate}">${x.name}</option>`).join("")}</select></label><label>Quantity<input name="quantity" type="number" min=".01" step=".01" value="1" required></label><label>Purchase unit<input name="unit" placeholder="case / piece"></label><label>Unit cost<input name="unitCost" type="number" min="0" step=".01" value="0" required></label><label>Discount<input name="discount" type="number" min="0" step=".01" value="0"></label><label>Tax %<input name="taxRate" type="number" min="0" step=".01" value="0"></label><label>Batch<input name="batchNumber"></label><label>Expiry<input name="expiry" type="date"></label><button class="secondary full" type="button" onclick="this.closest('.purchase-line').remove();calculatePurchase()">Remove line</button>`;$("#purchaseItems").append(row);const select=row.querySelector("select"),inputs=row.querySelectorAll("input");select.onchange=()=>{const option=select.selectedOptions[0];row.querySelector('[name="unitCost"]').value=option.dataset.cost||0;row.querySelector('[name="taxRate"]').value=option.dataset.tax||0;calculatePurchase()};inputs.forEach(input=>input.oninput=calculatePurchase);calculatePurchase()};
window.calculatePurchase=()=>{const lines=[...document.querySelectorAll(".purchase-line")],shipping=Number($("#purchaseForm")?.elements.shipping.value||0),other=Number($("#purchaseForm")?.elements.otherCosts.value||0);let subtotal=0,discount=0,tax=0;for(const row of lines){const quantity=Number(row.querySelector('[name="quantity"]').value||0),cost=Number(row.querySelector('[name="unitCost"]').value||0),d=Number(row.querySelector('[name="discount"]').value||0),rate=Number(row.querySelector('[name="taxRate"]').value||0);subtotal+=quantity*cost;discount+=d;tax+=(quantity*cost-d)*rate/100}if($("#purchaseTotal"))$("#purchaseTotal").innerHTML=`Subtotal ${money(subtotal)} • Discount ${money(discount)} • Tax ${money(tax)} • <b>Total ${money(subtotal-discount+tax+shipping+other)}</b>`};
async function submitPurchase(event){event.preventDefault();try{const form=event.target,raw=Object.fromEntries(new FormData(form)),items=[...document.querySelectorAll(".purchase-line")].map(row=>Object.fromEntries(new FormData(row))),file=form.elements.document.files[0],payload={...raw,items};delete payload.document;if(file){if(file.size>500000)throw Error("Document must be smaller than 500 KB.");payload.documentName=file.name;payload.documentData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}await api("/api/grocery/purchases",{method:"POST",body:JSON.stringify(payload)});closeM();toast("Purchase order created");route("purchases")}catch(error){toast(error.message,true)}}
window.approvePurchase=async(id,approve)=>{try{await api(`/api/grocery/purchases/${id}/approve`,{method:"POST",body:JSON.stringify({approve})});toast(approve?"Purchase approved":"Purchase rejected");route("purchases")}catch(error){toast(error.message,true)}};
window.receivePurchase=id=>{const p=purchaseRows.find(x=>x.id===id);modal(`Receive ${p.poNumber||p.id}`,`<form id="receiveForm" class="form"><div class="alert full">Enter only the quantities received now. Rejected quantity does not increase stock.</div>${p.items.map(i=>`<div class="full form" data-item="${i.id}" style="border:1px solid var(--line);padding:10px"><b class="full">${i.productName} — ordered ${i.orderedQty}, previously received ${i.receivedQty||0}</b><label>Receive now<input name="quantity" type="number" min="0" max="${i.orderedQty-(i.receivedQty||0)-(i.rejectedQty||0)}" step=".01" value="0"></label><label>Reject / damaged<input name="rejected" type="number" min="0" step=".01" value="0"></label><label>Batch<input name="batchNumber" value="${i.batchNumber||""}"></label><label>Expiry<input name="expiry" type="date" value="${i.expiry||""}"></label></div>`).join("")}<button class="primary full">Post goods received</button></form>`);$("#receiveForm").onsubmit=async event=>{event.preventDefault();try{const items=[...event.target.querySelectorAll('[data-item]')].map(row=>({itemId:row.dataset.item,...Object.fromEntries(new FormData(row))}));await api(`/api/grocery/purchases/${id}/receive`,{method:"POST",body:JSON.stringify({items})});closeM();toast("Receiving posted and inventory updated");route("purchases")}catch(error){toast(error.message,true)}}};
window.payPurchase=id=>{const p=purchaseRows.find(x=>x.id===id);modal(`Pay ${p.poNumber||p.id}`,`<form id="purchasePayForm" class="form"><div class="alert full">Outstanding: <b>${money(p.outstanding??p.total)}</b>. You can split this payment.</div><label>Cash<input name="cash" type="number" min="0" step=".01" value="0"></label><label>eSewa<input name="esewa" type="number" min="0" step=".01" value="0"></label><label>Khalti<input name="khalti" type="number" min="0" step=".01" value="0"></label><label>Bank<input name="bank" type="number" min="0" step=".01" value="0"></label><label>Bank name<input name="bankName"></label><label>Bank transaction details<input name="bankDetails"></label><label class="full">Payment date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><button class="primary full">Record supplier payment</button></form>`);$("#purchasePayForm").onsubmit=async event=>{event.preventDefault();try{const r=Object.fromEntries(new FormData(event.target)),payments=[{method:"Cash",amount:Number(r.cash||0)},{method:"eSewa",amount:Number(r.esewa||0)},{method:"Khalti",amount:Number(r.khalti||0)},{method:"Bank",amount:Number(r.bank||0),bankName:r.bankName,bankDetails:r.bankDetails}].filter(x=>x.amount>0);await api(`/api/grocery/purchases/${id}/pay`,{method:"POST",body:JSON.stringify({date:r.date,payments})});closeM();toast("Supplier payment recorded");route("purchases")}catch(error){toast(error.message,true)}}};
window.returnPurchase=id=>{const p=purchaseRows.find(x=>x.id===id),available=p.items.filter(i=>Number(i.receivedQty)>Number(i.returnedQty||0));modal(`Return goods: ${p.poNumber||p.id}`,`<form id="returnPurchaseForm" class="form"><label class="full">Product<select name="itemId">${available.map(i=>`<option value="${i.id}">${i.productName} — returnable ${i.receivedQty-(i.returnedQty||0)}</option>`).join("")}</select></label><label>Quantity<input name="quantity" type="number" min=".01" step=".01" required></label><label>Reason<input name="reason" required placeholder="Damaged, expired or incorrect item"></label><button class="primary full">Post supplier return</button></form>`);$("#returnPurchaseForm").onsubmit=async event=>{event.preventDefault();try{await api(`/api/grocery/purchases/${id}/return`,{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});closeM();toast("Supplier return posted");route("purchases")}catch(error){toast(error.message,true)}}};
window.purchaseHistory=id=>{const p=purchaseRows.find(x=>x.id===id);modal(`History: ${p.poNumber||p.id}`,`<div>${(p.history||[]).slice().reverse().map(h=>`<div class="alert"><b>${h.action}</b><br><small>${h.user} • ${new Date(h.at).toLocaleString()}</small></div>`).join("")||"No history available."}</div>`)};
window.openPurchaseDocument=id=>{const p=purchaseRows.find(x=>x.id===id);if(p?.documentData)window.open(p.documentData,"_blank")};
window.printPurchase=id=>{const p=purchaseRows.find(x=>x.id===id),popup=window.open("","_blank");popup.document.write(`<html><head><title>${p.poNumber||p.id}</title><style>body{font:14px Arial;padding:30px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #bbb;padding:8px;text-align:left}</style></head><body><h1>Purchase order ${p.poNumber||p.id}</h1><p><b>Supplier:</b> ${p.supplier}<br><b>Invoice:</b> ${p.supplierInvoice||"—"}<br><b>Date:</b> ${date(p.date)}</p><table><tr><th>Product</th><th>Quantity</th><th>Rate</th><th>Tax</th><th>Total</th></tr>${(p.items||[]).map(i=>`<tr><td>${i.productName}</td><td>${i.orderedQty} ${i.unit}</td><td>${money(i.unitCost)}</td><td>${money(i.tax)}</td><td>${money(i.orderedQty*i.unitCost-i.discount+i.tax)}</td></tr>`).join("")}</table><h2>Total: ${money(p.total)}</h2><p>Status: ${p.status} • Payment: ${p.paymentStatus}</p></body></html>`);popup.document.close();popup.print()};
window.exportPurchases=()=>{const rows=[["PO","Invoice","Supplier","Date","Expected","Total","Paid","Outstanding","Receiving","Payment","Status"],...purchaseRows.map(p=>[p.poNumber||p.id,p.supplierInvoice,p.supplier,p.date,p.expectedDate,p.total,p.paidAmount,p.outstanding??p.total,p.receivingStatus,p.paymentStatus,p.status])],csv=rows.map(row=>row.map(value=>`"${String(value??"").replaceAll('"','""')}"`).join(",")).join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="freshmart-purchases.csv";a.click()};
pages.suppliers=async()=>{const [suppliers,purchases,products]=await Promise.all([api("/api/grocery/suppliers"),api("/api/grocery/purchases"),api("/api/grocery/products")]);window.supplierRows=suppliers;window.supplierPurchases=purchases;window.supplierProducts=products;const active=suppliers.filter(x=>!x.archived&&x.status==="Active").length,totalBalance=suppliers.reduce((s,x)=>s+Number(x.balance||0),0);$("#gcontent").innerHTML=head("Suppliers","Business details, product links, payables and performance",`<div><button class="secondary" onclick="exportSuppliers()">Export CSV</button> <button class="primary" onclick="newSupplier()">+ Add supplier</button></div>`)+`<div class="grid3"><div class="stat"><small>Active suppliers</small><b>${active}</b><em>${suppliers.length} total records</em></div><div class="stat"><small>Total payable</small><b>${money(totalBalance)}</b><em>Current supplier balances</em></div><div class="stat"><small>Primary suppliers</small><b>${suppliers.filter(x=>x.primary&&!x.archived).length}</b><em>Preferred purchasing sources</em></div></div><div class="card"><div class="search"><input id="supplierSearch" placeholder="Search supplier, code, contact, tax, category or bank…"><select id="supplierStatus"><option value="">All statuses</option><option>Active</option><option>Inactive</option><option>Archived</option></select><small id="supplierCount">${suppliers.length} suppliers</small></div><div id="supplierRows">${supplierTable(suppliers)}</div></div>`;const filter=()=>{const term=$("#supplierSearch").value.toLowerCase(),status=$("#supplierStatus").value,rows=suppliers.filter(x=>(!status||x.status===status)&&[x.id,x.code,x.name,x.legalName,x.contact,x.email,x.phone,x.panVat,x.registrationNumber,x.category,x.bankName,x.assignedUser].some(v=>String(v||"").toLowerCase().includes(term)));$("#supplierRows").innerHTML=supplierTable(rows);$("#supplierCount").textContent=`${rows.length} of ${suppliers.length} suppliers`};$("#supplierSearch").oninput=filter;$("#supplierStatus").onchange=filter};
function supplierTable(rows){return table(["Supplier","Contact","Business / tax","Categories","Bank / wallets","Terms","Purchases / payable","Performance","Status","Actions"],rows.map(s=>{const purchases=supplierPurchases.filter(p=>p.supplierId===s.id||p.supplier===s.name),linked=supplierProducts.filter(p=>p.supplier===s.name);return`<tr><td><b>${s.name}</b>${s.primary?' <span class="badge green">Primary</span>':""}<br><small>${s.code||s.id}<br>${s.legalName||""}</small></td><td>${s.contact||"—"}<br><small>${s.email||""}<br>${s.phone||""}</small></td><td>${s.panVat||"No PAN/VAT"}<br><small>${s.registrationNumber||"No registration"}</small></td><td>${s.category||"General"}<br><small>${(s.productCategories||[]).join(", ")||`${linked.length} linked products`}</small></td><td>${s.bankName||"—"}<br><small>${s.esewa?`eSewa ${s.esewa}<br>`:""}${s.khalti?`Khalti ${s.khalti}`:""}</small></td><td>${s.paymentTerms||0} days<br><small>Limit ${money(s.creditLimit)}<br>${s.defaultPaymentMethod||"—"}</small></td><td>${purchases.length} orders<br><b>${money(s.balance)}</b><br><small>Current payable</small></td><td>Delivery ${Number(s.deliveryRating||0).toFixed(1)} ★<br><small>Quality ${Number(s.qualityRating||0).toFixed(1)} ★</small></td><td><span class="badge ${s.status==="Active"?"green":"orange"}">${s.status}</span><br><small>${s.assignedUser||"Unassigned"}</small></td><td><div style="display:grid;gap:5px"><button class="secondary" onclick="supplierDetails('${s.id}')">Statement</button><button class="secondary" onclick="editSupplier('${s.id}')">Edit</button><button class="secondary" onclick="supplierDocuments('${s.id}')">Documents</button>${!s.archived?`<button class="secondary" onclick="archiveSupplier('${s.id}')">Archive</button>`:""}</div></td></tr>`}).join(""))}
const supplierForm=s=>`<form id="supplierForm" class="form"><label>Supplier code<input name="code" value="${s?.code||""}" placeholder="Auto-generated if blank"></label><label>Trading name<input name="name" value="${s?.name||""}" required></label><label class="full">Legal / registered name<input name="legalName" value="${s?.legalName||""}"></label><label>Contact person<input name="contact" value="${s?.contact||""}"></label><label>Email<input name="email" type="email" value="${s?.email||""}"></label><label>Primary phone<input name="phone" value="${s?.phone||""}"></label><label>Secondary phone<input name="secondaryPhone" value="${s?.secondaryPhone||""}"></label><label class="full">Billing address<textarea name="billingAddress">${s?.billingAddress||""}</textarea></label><label class="full">Delivery address<textarea name="deliveryAddress">${s?.deliveryAddress||""}</textarea></label><label>PAN / VAT number<input name="panVat" value="${s?.panVat||""}"></label><label>Registration number<input name="registrationNumber" value="${s?.registrationNumber||""}"></label><label>Supplier category<input name="category" value="${s?.category||"General"}"></label><label>Product categories<input name="productCategoriesText" value="${(s?.productCategories||[]).join(", ")}" placeholder="Dairy, beverages, produce"></label><label>Bank name<input name="bankName" value="${s?.bankName||""}"></label><label>Bank branch<input name="bankBranch" value="${s?.bankBranch||""}"></label><label>Account name<input name="accountName" value="${s?.accountName||""}"></label><label>Account number<input name="accountNumber" value="${s?.accountNumber||""}"></label><label>eSewa account<input name="esewa" value="${s?.esewa||""}"></label><label>Khalti account<input name="khalti" value="${s?.khalti||""}"></label><label>Opening balance<input name="openingBalance" type="number" min="0" step=".01" value="${s?.openingBalance||0}"></label><label>Credit limit<input name="creditLimit" type="number" min="0" step=".01" value="${s?.creditLimit||0}"></label><label>Payment terms (days)<input name="paymentTerms" type="number" min="0" value="${s?.paymentTerms??30}"></label><label>Default payment<select name="defaultPaymentMethod">${["Cash","eSewa","Khalti","Bank"].map(x=>`<option ${x===(s?.defaultPaymentMethod||"Bank")?"selected":""}>${x}</option>`).join("")}</select></label><label>Currency<input name="currency" value="${s?.currency||gb.settings.currency}"></label><label>Assigned employee<input name="assignedUser" value="${s?.assignedUser||""}"></label><label>Delivery rating (0–5)<input name="deliveryRating" type="number" min="0" max="5" step=".1" value="${s?.deliveryRating||0}"></label><label>Quality rating (0–5)<input name="qualityRating" type="number" min="0" max="5" step=".1" value="${s?.qualityRating||0}"></label><label>Status<select name="status">${["Active","Inactive"].map(x=>`<option ${x===(s?.status||"Active")?"selected":""}>${x}</option>`).join("")}</select></label><label><input name="primary" type="checkbox" ${s?.primary?"checked":""}> Primary/preferred supplier</label><label class="full">Internal notes<textarea name="notes">${s?.notes||""}</textarea></label><button class="primary full">${s?"Save supplier":"Create supplier"}</button></form>`;
window.newSupplier=()=>{modal("Add supplier",supplierForm());bindSupplier()};window.editSupplier=id=>{const s=supplierRows.find(x=>x.id===id);modal(`Edit ${s.name}`,supplierForm(s));bindSupplier(id)};function bindSupplier(id){$("#supplierForm").onsubmit=async event=>{event.preventDefault();try{const raw=Object.fromEntries(new FormData(event.target)),payload={...raw,primary:event.target.elements.primary.checked,productCategories:String(raw.productCategoriesText||"").split(",").map(x=>x.trim()).filter(Boolean)};delete payload.productCategoriesText;await api(id?`/api/grocery/suppliers/${id}`:"/api/grocery/suppliers",{method:id?"PATCH":"POST",body:JSON.stringify(payload)});closeM();toast("Supplier saved");route("suppliers")}catch(error){toast(error.message,true)}}}
window.supplierDetails=async id=>{const d=await api(`/api/grocery/suppliers/${id}/statement`),s=d.supplier;modal(`Supplier statement: ${s.name}`,`<div class="grid3"><div class="stat"><small>Purchases</small><b>${money(d.totals.purchases)}</b></div><div class="stat"><small>Paid</small><b>${money(d.totals.paid)}</b></div><div class="stat"><small>Outstanding</small><b>${money(d.totals.outstanding)}</b></div></div><p><b>${s.legalName}</b><br>${s.billingAddress||""}<br>PAN/VAT: ${s.panVat||"—"}<br>Payment terms: ${s.paymentTerms} days</p><h3>Linked products (${d.products.length})</h3><p>${d.products.map(x=>x.name).join(", ")||"No linked products."}</p><h3>Purchase and payment history</h3>${table(["PO","Date","Total","Paid","Outstanding","Status"],d.purchases.map(p=>`<tr><td>${p.poNumber||p.id}</td><td>${date(p.date)}</td><td>${money(p.total)}</td><td>${money(p.paidAmount)}</td><td>${money(p.outstanding??p.total)}</td><td>${p.paymentStatus||p.status}</td></tr>`).join(""))}<h3>Activity</h3>${(s.history||[]).slice().reverse().map(h=>`<div class="alert"><b>${h.action}</b><br><small>${h.user} • ${new Date(h.at).toLocaleString()}</small></div>`).join("")||"No activity."}<button class="primary" onclick="printSupplierStatement('${id}')">Print statement</button>`)};
window.supplierDocuments=id=>{const s=supplierRows.find(x=>x.id===id);modal(`Documents: ${s.name}`,`<div>${(s.documents||[]).map(d=>`<button class="secondary" onclick="openSupplierDocument('${id}','${d.id}')">${d.type}: ${d.name}</button>`).join(" ")||"No documents uploaded."}</div><form id="supplierDocumentForm" class="form" style="margin-top:18px"><label>Document type<select name="type"><option>Contract</option><option>Tax certificate</option><option>Business registration</option><option>Bank document</option><option>Other</option></select></label><label>File<input name="file" type="file" required></label><button class="primary full">Upload document</button></form>`);$("#supplierDocumentForm").onsubmit=async event=>{event.preventDefault();try{const file=event.target.elements.file.files[0];if(file.size>500000)throw Error("Document must be smaller than 500 KB.");const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});await api(`/api/grocery/suppliers/${id}/documents`,{method:"POST",body:JSON.stringify({name:file.name,type:event.target.elements.type.value,data})});closeM();toast("Supplier document uploaded");route("suppliers")}catch(error){toast(error.message,true)}}};
window.openSupplierDocument=async(supplierId,documentId)=>{const d=await api(`/api/grocery/suppliers/${supplierId}/documents/${documentId}`);window.open(d.data,"_blank")};window.archiveSupplier=async id=>{try{await api(`/api/grocery/suppliers/${id}/archive`,{method:"POST",body:"{}"});toast("Supplier archived");route("suppliers")}catch(error){toast(error.message,true)}};
window.printSupplierStatement=async id=>{const d=await api(`/api/grocery/suppliers/${id}/statement`),p=window.open("","_blank");p.document.write(`<html><head><title>${d.supplier.name}</title><style>body{font:14px Arial;padding:30px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbb;padding:8px}</style></head><body><h1>Supplier statement</h1><h2>${d.supplier.name}</h2><p>${d.supplier.billingAddress||""}<br>PAN/VAT: ${d.supplier.panVat||"—"}</p><table><tr><th>PO</th><th>Date</th><th>Total</th><th>Paid</th><th>Outstanding</th></tr>${d.purchases.map(x=>`<tr><td>${x.poNumber||x.id}</td><td>${x.date}</td><td>${money(x.total)}</td><td>${money(x.paidAmount)}</td><td>${money(x.outstanding??x.total)}</td></tr>`).join("")}</table><h2>Outstanding: ${money(d.totals.outstanding)}</h2></body></html>`);p.document.close();p.print()};
window.exportSuppliers=()=>{const rows=[["Code","Name","Legal name","Contact","Email","Phone","PAN/VAT","Category","Bank","Terms","Credit limit","Balance","Delivery rating","Quality rating","Status"],...supplierRows.map(s=>[s.code,s.name,s.legalName,s.contact,s.email,s.phone,s.panVat,s.category,s.bankName,s.paymentTerms,s.creditLimit,s.balance,s.deliveryRating,s.qualityRating,s.status])],csv=rows.map(row=>row.map(value=>`"${String(value??"").replaceAll('"','""')}"`).join(",")).join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="freshmart-suppliers.csv";a.click()};
pages.customers=async()=>{const d=await api("/api/grocery/customers");$("#gcontent").innerHTML=head("Customers & loyalty","Repeat shoppers and reward balances",`<button class="primary" onclick="newGroceryCustomer()">+ Add customer</button>`)+`<div class="card"><div class="search"><input id="groceryCustomerSearch" placeholder="Search customer, phone, email, tier or address…"><small id="groceryCustomerCount">${d.length} customers</small></div><div id="groceryCustomerRows">${groceryCustomerTable(d)}</div></div>`;$("#groceryCustomerSearch").oninput=event=>{const term=event.target.value.toLowerCase(),rows=term?d.filter(x=>[x.id,x.name,x.phone,x.email,x.address,x.tier,x.status,x.notes].some(v=>String(v||"").toLowerCase().includes(term))):d;$("#groceryCustomerRows").innerHTML=groceryCustomerTable(rows);$("#groceryCustomerCount").textContent=`${rows.length} of ${d.length} customers`}};
function groceryCustomerTable(d){return table(["Customer","Contact","Birthday / gender","Tier","Loyalty points","Lifetime spend","Status","Notes"],d.map(x=>`<tr><td><b>${x.name}</b><br><small>${x.id}</small></td><td>${x.phone}<br><small>${x.email||"—"}<br>${x.address||""}</small></td><td>${x.dob?date(x.dob):"—"}<br><small>${x.gender||""}</small></td><td><span class="badge green">${x.tier||"Regular"}</span></td><td><b>${Number(x.points||0)} points</b></td><td>${money(x.spent)}</td><td><span class="badge ${x.status==="Inactive"?"orange":"green"}">${x.status||"Active"}</span></td><td>${x.notes||"—"}</td></tr>`).join(""))}
window.newGroceryCustomer=()=>{modal("Add customer",`<form id="groceryCustomerForm" class="form"><label>Customer name<input name="name" required></label><label>Phone number<input name="phone" required></label><label>Email<input name="email" type="email"></label><label>Date of birth<input name="dob" type="date"></label><label>Gender<select name="gender"><option value="">Select</option><option>Female</option><option>Male</option><option>Other</option><option>Prefer not to say</option></select></label><label>Membership tier<select name="tier"><option>Regular</option><option>Silver</option><option>Gold</option><option>Platinum</option></select></label><label>Opening loyalty points<input name="points" type="number" min="0" value="0"></label><label>Opening lifetime spend<input name="spent" type="number" min="0" step=".01" value="0"></label><label>Status<select name="status"><option>Active</option><option>Inactive</option></select></label><label class="full">Address<textarea name="address"></textarea></label><label class="full">Customer notes<textarea name="notes"></textarea></label><button class="primary full">Save customer</button></form>`);$("#groceryCustomerForm").onsubmit=async event=>{event.preventDefault();try{await api("/api/grocery/customers",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});closeM();toast("Customer added");route("customers")}catch(error){toast(error.message,true)}}};
pages.expenses=async()=>{const d=await api("/api/grocery/expenses");window.expenseRows=d;const active=d.filter(x=>!x.reversed),total=active.reduce((s,x)=>s+Number(x.total||x.amount||0),0),paid=active.reduce((s,x)=>s+Number(x.paidAmount||0),0);$("#gcontent").innerHTML=head("Expenses","Approval, payment, tax and recurring cost management",`<div><button class="secondary" onclick="exportExpenses()">Export CSV</button> <button class="primary" onclick="newExpense()">+ Record expense</button></div>`)+`<div class="grid3"><div class="stat"><small>Total expenses</small><b>${money(total)}</b><em>${active.length} active records</em></div><div class="stat"><small>Paid</small><b>${money(paid)}</b><em>Completed and partial payments</em></div><div class="stat"><small>Outstanding</small><b>${money(total-paid)}</b><em>Still payable</em></div></div><div class="card"><div class="search"><input id="expenseSearch" placeholder="Search reference, payee, category, department or payment…"><input id="expenseFrom" type="date"><input id="expenseTo" type="date"><select id="expenseStatus"><option value="">All statuses</option><option>Pending approval</option><option>Approved</option><option>Rejected</option><option>Reversed</option><option>Paid</option><option>Partially paid</option><option>Unpaid</option></select><small id="expenseCount">${d.length} expenses</small></div><div id="expenseRows">${expenseTable(d)}</div></div>`;const filter=()=>{const term=$("#expenseSearch").value.toLowerCase(),from=$("#expenseFrom").value,to=$("#expenseTo").value,status=$("#expenseStatus").value,rows=d.filter(x=>(!from||x.date>=from)&&(!to||x.date<=to)&&(!status||x.status===status||x.paymentStatus===status)&&[x.id,x.reference,x.payee,x.category,x.subcategory,x.description,x.department,x.costCentre,x.linkedReference,...(x.payments||[]).flatMap(p=>[p.method,p.bankName,p.bankDetails])].some(v=>String(v||"").toLowerCase().includes(term)));$("#expenseRows").innerHTML=expenseTable(rows);$("#expenseCount").textContent=`${rows.length} of ${d.length} expenses`};[$("#expenseSearch"),$("#expenseFrom"),$("#expenseTo"),$("#expenseStatus")].forEach(x=>x.oninput=filter)};
function expenseTable(rows){return table(["Reference / date","Payee / link","Category / cost centre","Description","Tax / currency","Total","Payment","Workflow","Recurring / receipt","Audit","Actions"],rows.map(e=>`<tr><td><b>${e.reference||e.id}</b><br><small>${date(e.date)}<br>Due ${e.dueDate?date(e.dueDate):"—"}</small></td><td>${e.payee||"—"}<br><small>${e.payeeType||""}<br>${e.linkedReference||""}</small></td><td>${e.category}<br><small>${e.subcategory||""}<br>${e.department||""} ${e.costCentre||""}</small></td><td>${e.description}<br><small>${e.quantity||1} × ${money(e.unitRate||e.amount)}</small></td><td>VAT ${Number(e.taxRate||0)}%: ${money(e.tax)}<br><small>${e.currency||gb.settings.currency} @ ${e.exchangeRate||1}${e.taxDeductible?" • deductible":""}</small></td><td><b>${money(e.total||e.amount)}</b><br><small>Discount ${money(e.discount)}</small></td><td><b>${e.paymentStatus||"Unpaid"}</b><br><small>Paid ${money(e.paidAmount)}<br>Due ${money(e.outstanding)}</small></td><td><span class="badge ${e.status==="Approved"?"green":"orange"}">${e.status}</span><br><small>${e.approvedBy||""}</small></td><td>${e.recurring?`${e.frequency}<br><small>Next ${e.nextPaymentDate?date(e.nextPaymentDate):"—"}</small>`:"One-time"}<br>${e.receiptData?`<button class="secondary" onclick="openExpenseReceipt('${e.id}')">Receipt</button>`:""}</td><td>${e.createdBy||"System"}<br><button class="secondary" onclick="expenseHistory('${e.id}')">History</button></td><td><div style="display:grid;gap:5px">${e.status==="Pending approval"?`<button class="primary" onclick="approveExpense('${e.id}',true)">Approve</button>`:""}${e.status==="Approved"&&Number(e.outstanding)>0?`<button class="secondary" onclick="payExpense('${e.id}')">Pay</button>`:""}${!e.reversed?`<button class="secondary" onclick="reverseExpense('${e.id}')">Reverse</button>`:""}<button class="secondary" onclick="printExpense('${e.id}')">Print</button></div></td></tr>`).join(""))}
window.newExpense=()=>{modal("Record expense",`<form id="expenseForm" class="form"><label>Reference<input name="reference" placeholder="Auto-generated if blank"></label><label>Expense date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Due date<input name="dueDate" type="date"></label><label>Payee type<select name="payeeType"><option>Supplier</option><option>Employee</option><option>Government</option><option>Other</option></select></label><label>Payee<input name="payee"></label><label>Category<input name="category" list="expenseCategories" required><datalist id="expenseCategories"><option>Utilities</option><option>Rent</option><option>Salary</option><option>Transport</option><option>Maintenance</option><option>Marketing</option><option>Tax</option><option>Other</option></datalist></label><label>Subcategory<input name="subcategory"></label><label class="full">Description<input name="description" required></label><label>Quantity<input name="quantity" type="number" min=".01" step=".01" value="1"></label><label>Unit rate<input name="unitRate" type="number" min="0" step=".01" value="0" required></label><label>Discount<input name="discount" type="number" min="0" step=".01" value="0"></label><label>VAT / tax %<input name="taxRate" type="number" min="0" step=".01" value="0"></label><div id="expenseTotal" class="alert full"></div><label>PAN / VAT number<input name="panVat"></label><label><input name="taxDeductible" type="checkbox"> Tax deductible</label><label>Department<input name="department"></label><label>Branch<input name="branch" value="Kathmandu HQ"></label><label>Cost centre<input name="costCentre"></label><label>Linked purchase/supplier/employee<input name="linkedReference"></label><label>Currency<input name="currency" value="${gb.settings.currency}"></label><label>Exchange rate<input name="exchangeRate" type="number" min=".000001" step=".000001" value="1"></label><label>Status<select name="status"><option>Approved</option><option>Draft</option></select></label><label><input name="reimbursement" type="checkbox"> Employee reimbursement</label><label>Employee<input name="employee"></label><label><input name="recurring" type="checkbox"> Recurring expense</label><label>Frequency<select name="frequency"><option>Weekly</option><option>Monthly</option><option>Quarterly</option><option>Yearly</option></select></label><label>Next payment date<input name="nextPaymentDate" type="date"></label><label class="full">Receipt / invoice<input name="receipt" type="file" accept="image/*,.pdf"></label><label class="full">Notes<textarea name="notes"></textarea></label><label class="full">Internal remarks<textarea name="internalNotes"></textarea></label><button class="primary full">Create expense</button></form>`);const form=$("#expenseForm"),sync=()=>{const q=Number(form.elements.quantity.value||0),rate=Number(form.elements.unitRate.value||0),discount=Number(form.elements.discount.value||0),taxRate=Number(form.elements.taxRate.value||0),sub=q*rate,tax=(sub-discount)*taxRate/100;$("#expenseTotal").innerHTML=`Subtotal ${money(sub)} • Tax ${money(tax)} • <b>Total ${money(sub-discount+tax)}</b>`};[form.elements.quantity,form.elements.unitRate,form.elements.discount,form.elements.taxRate].forEach(x=>x.oninput=sync);sync();form.onsubmit=async event=>{event.preventDefault();try{const raw=Object.fromEntries(new FormData(form)),receipt=form.elements.receipt.files[0],payload={...raw,taxDeductible:form.elements.taxDeductible.checked,recurring:form.elements.recurring.checked,reimbursement:form.elements.reimbursement.checked};delete payload.receipt;if(receipt){if(receipt.size>500000)throw Error("Receipt must be smaller than 500 KB.");payload.receiptName=receipt.name;payload.receiptData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(receipt)})}await api("/api/grocery/expenses",{method:"POST",body:JSON.stringify(payload)});closeM();toast("Expense created");route("expenses")}catch(error){toast(error.message,true)}}};
window.approveExpense=async(id,approve)=>{try{await api(`/api/grocery/expenses/${id}/approve`,{method:"POST",body:JSON.stringify({approve})});toast(approve?"Expense approved":"Expense rejected");route("expenses")}catch(error){toast(error.message,true)}};window.payExpense=id=>{const e=expenseRows.find(x=>x.id===id);modal(`Pay ${e.reference}`,`<form id="expensePayForm" class="form"><div class="alert full">Outstanding: <b>${money(e.outstanding)}</b>. Split payment is allowed.</div><label>Cash<input name="cash" type="number" min="0" step=".01" value="0"></label><label>eSewa<input name="esewa" type="number" min="0" step=".01" value="0"></label><label>Khalti<input name="khalti" type="number" min="0" step=".01" value="0"></label><label>Bank<input name="bank" type="number" min="0" step=".01" value="0"></label><label>Bank name<input name="bankName"></label><label>Bank details<input name="bankDetails"></label><label class="full">Payment date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><button class="primary full">Record payment</button></form>`);$("#expensePayForm").onsubmit=async event=>{event.preventDefault();try{const r=Object.fromEntries(new FormData(event.target)),payments=[{method:"Cash",amount:Number(r.cash||0)},{method:"eSewa",amount:Number(r.esewa||0)},{method:"Khalti",amount:Number(r.khalti||0)},{method:"Bank",amount:Number(r.bank||0),bankName:r.bankName,bankDetails:r.bankDetails}].filter(x=>x.amount>0);await api(`/api/grocery/expenses/${id}/pay`,{method:"POST",body:JSON.stringify({date:r.date,payments})});closeM();toast("Expense payment recorded");route("expenses")}catch(error){toast(error.message,true)}}};
window.reverseExpense=id=>{modal("Reverse expense",`<form id="reverseExpenseForm" class="form"><label class="full">Reason for reversal<textarea name="reason" required></textarea></label><button class="primary full">Reverse posted expense</button></form>`);$("#reverseExpenseForm").onsubmit=async event=>{event.preventDefault();try{await api(`/api/grocery/expenses/${id}/reverse`,{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});closeM();toast("Expense reversed");route("expenses")}catch(error){toast(error.message,true)}}};window.openExpenseReceipt=id=>{const e=expenseRows.find(x=>x.id===id);if(e?.receiptData)window.open(e.receiptData,"_blank")};window.expenseHistory=id=>{const e=expenseRows.find(x=>x.id===id);modal(`History: ${e.reference}`,`<div>${(e.history||[]).slice().reverse().map(h=>`<div class="alert"><b>${h.action}</b><br><small>${h.user} • ${new Date(h.at).toLocaleString()}</small></div>`).join("")||"No activity."}</div>`)};
window.printExpense=id=>{const e=expenseRows.find(x=>x.id===id),p=window.open("","_blank");p.document.write(`<html><head><title>${e.reference}</title><style>body{font:14px Arial;padding:35px}dl{display:grid;grid-template-columns:180px 1fr}dt,dd{padding:8px;border-bottom:1px solid #ddd;margin:0}</style></head><body><h1>Expense voucher</h1><dl><dt>Reference</dt><dd>${e.reference}</dd><dt>Date</dt><dd>${e.date}</dd><dt>Payee</dt><dd>${e.payee||"—"}</dd><dt>Category</dt><dd>${e.category} / ${e.subcategory||"—"}</dd><dt>Description</dt><dd>${e.description}</dd><dt>Subtotal</dt><dd>${money(e.subtotal)}</dd><dt>Tax</dt><dd>${money(e.tax)}</dd><dt>Total</dt><dd><b>${money(e.total)}</b></dd><dt>Payment</dt><dd>${e.paymentStatus}</dd><dt>Status</dt><dd>${e.status}</dd></dl></body></html>`);p.document.close();p.print()};window.exportExpenses=()=>{const rows=[["Reference","Date","Payee","Category","Subcategory","Description","Subtotal","Tax","Total","Paid","Outstanding","Payment status","Workflow","Currency","Department","Cost centre"],...expenseRows.map(e=>[e.reference,e.date,e.payee,e.category,e.subcategory,e.description,e.subtotal,e.tax,e.total,e.paidAmount,e.outstanding,e.paymentStatus,e.status,e.currency,e.department,e.costCentre])],csv=rows.map(row=>row.map(value=>`"${String(value??"").replaceAll('"','""')}"`).join(",")).join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="freshmart-expenses.csv";a.click()};
function saleTable(d){return table(["Receipt","Date","Items","Payment breakdown","Cashier","Total"],d.map(x=>`<tr><td><b>${x.receipt}</b></td><td>${date(x.createdAt)}</td><td>${x.items.reduce((a,i)=>a+i.qty,0)}</td><td>${x.payments?.length?x.payments.map(p=>`${p.method}: ${money(p.amount)}${p.bankName?` (${p.bankName})`:""}`).join("<br>"):x.payment}</td><td>${x.cashier}</td><td><b>${money(x.total)}</b></td></tr>`).join(""))}
pages.saleslog=async()=>{const sales=await api("/api/grocery/sales"),methodTotal=method=>sales.reduce((sum,sale)=>sum+(sale.payments||[]).filter(x=>x.method===method).reduce((a,x)=>a+Number(x.amount||0),0),0),grand=sales.reduce((sum,sale)=>sum+Number(sale.total||0),0);$("#gcontent").innerHTML=head("Sales log","Search every receipt and review its complete payment breakdown")+`<div class="grid3"><div class="stat"><small>Total collected</small><b>${money(grand)}</b><em>${sales.length} transactions</em></div><div class="stat"><small>Cash</small><b>${money(methodTotal("Cash"))}</b><em>Cash drawer</em></div><div class="stat"><small>Digital & bank</small><b>${money(methodTotal("eSewa")+methodTotal("Khalti")+methodTotal("Bank"))}</b><em>eSewa, Khalti and Bank</em></div></div><div class="card"><div class="search"><input id="saleLogSearch" placeholder="Search receipt, product, cashier, customer, payment or bank…"><small id="saleLogCount">${sales.length} sales</small></div><div id="saleLogRows">${saleTable(sales)}</div></div>`;$("#saleLogSearch").oninput=event=>{const term=event.target.value.trim().toLowerCase(),rows=term?sales.filter(sale=>[sale.id,sale.receipt,sale.customer,sale.cashier,sale.createdAt,...sale.items.flatMap(x=>[x.name,x.id]),...(sale.payments||[]).flatMap(x=>[x.method,x.amount,x.bankName,x.bankDetails])].some(value=>String(value||"").toLowerCase().includes(term))):sales;$("#saleLogRows").innerHTML=saleTable(rows);$("#saleLogCount").textContent=`${rows.length} of ${sales.length} sales`}};
pages.reports=async()=>{const [s,p,e]=await Promise.all([api("/api/grocery/sales"),api("/api/grocery/products"),api("/api/grocery/expenses")]);const sales=s.reduce((a,x)=>a+x.total,0),profit=s.reduce((a,x)=>a+x.profit,0),expenses=e.reduce((a,x)=>a+x.amount,0);$("#gcontent").innerHTML=head("Business reports","Sales, inventory and estimated profitability")+`<div class="grid3"><div class="stat"><small>Total sales</small><b>${money(sales)}</b></div><div class="stat"><small>Gross profit</small><b>${money(profit)}</b></div><div class="stat"><small>Net after expenses</small><b>${money(profit-expenses)}</b></div></div><div class="grid2"><div class="card"><h3>Sales register</h3>${saleTable(s)}</div><div class="card"><h3>Stock valuation</h3><p>At cost: <b>${money(p.reduce((a,x)=>a+x.cost*x.stock,0))}</b></p><p>At retail: <b>${money(p.reduce((a,x)=>a+x.price*x.stock,0))}</b></p><p>Potential margin: <b>${money(p.reduce((a,x)=>a+(x.price-x.cost)*x.stock,0))}</b></p></div></div>`};
pages.audit=async()=>{const d=await api("/api/grocery/audit");$("#gcontent").innerHTML=head("Audit log","Permanent history of store actions")+`<div class="card">${table(["Event","Action","Detail","Date & time"],d.map(x=>`<tr><td>${x.id}</td><td><b>${x.action.replaceAll("_"," ")}</b></td><td>${x.detail}</td><td>${new Date(x.createdAt).toLocaleString()}</td></tr>`).join(""))}</div>`};
submitPurchase=async function(event){event.preventDefault();try{const form=event.target,raw=Object.fromEntries(new FormData(form)),items=[...document.querySelectorAll(".purchase-line")].map(row=>Object.fromEntries([...row.querySelectorAll("[name]")].map(input=>[input.name,input.value]))),file=form.elements.document.files[0],payload={...raw,items};delete payload.document;if(file){if(file.size>500000)throw Error("Document must be smaller than 500 KB.");payload.documentName=file.name;payload.documentData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}await api("/api/grocery/purchases",{method:"POST",body:JSON.stringify(payload)});closeM();toast("Purchase order created");route("purchases")}catch(error){toast(error.message,true)}};
window.receivePurchase=id=>{const p=purchaseRows.find(x=>x.id===id);modal(`Receive ${p.poNumber||p.id}`,`<form id="receiveForm" class="form"><div class="alert full">Enter only quantities received now. Rejected quantity does not increase stock.</div>${p.items.map(i=>`<div class="full form" data-item="${i.id}" style="border:1px solid var(--line);padding:10px"><b class="full">${i.productName} — ordered ${i.orderedQty}, previously received ${i.receivedQty||0}</b><label>Receive now<input name="quantity" type="number" min="0" max="${i.orderedQty-(i.receivedQty||0)-(i.rejectedQty||0)}" step=".01" value="0"></label><label>Reject / damaged<input name="rejected" type="number" min="0" step=".01" value="0"></label><label>Batch<input name="batchNumber" value="${i.batchNumber||""}"></label><label>Expiry<input name="expiry" type="date" value="${i.expiry||""}"></label></div>`).join("")}<button class="primary full">Post goods received</button></form>`);$("#receiveForm").onsubmit=async event=>{event.preventDefault();try{const items=[...event.target.querySelectorAll('[data-item]')].map(row=>({itemId:row.dataset.item,...Object.fromEntries([...row.querySelectorAll("[name]")].map(input=>[input.name,input.value]))}));await api(`/api/grocery/purchases/${id}/receive`,{method:"POST",body:JSON.stringify({items})});closeM();toast("Receiving posted and inventory updated");route("purchases")}catch(error){toast(error.message,true)}}};
window.route=route;init();
